/** Return a scalar's terminal-cell width, using the selected UAX #11 ambiguous policy. */
[[nodiscard]] constexpr auto of(const char32_t codepoint,
                                 const bool ambiguous_is_wide = false) noexcept -> int {
    if (codepoint < 0x20 || (codepoint >= 0x7f && codepoint <= 0x9f) ||
        detail::in_intervals(codepoint, detail::zero_width)) {
        return 0;
    }
    if (detail::in_intervals(codepoint, detail::wide) ||
        (ambiguous_is_wide && detail::in_intervals(codepoint, detail::ambiguous))) {
        return 2;
    }
    return 1;
}

/** Return whether a scalar uses two cells with the default width policy. */
[[nodiscard]] constexpr auto is_wide(const char32_t codepoint) noexcept -> bool {
    return of(codepoint) == 2;
}

/** Return whether a scalar uses no terminal cells. */
[[nodiscard]] constexpr auto is_zero(const char32_t codepoint) noexcept -> bool {
    return of(codepoint) == 0;
}

/** Sum scalar widths in UTF-8 text; use of_grapheme() for a single cluster. */
[[nodiscard]] inline auto of_string(const std::string_view text,
                                    const bool ambiguous_is_wide = false) noexcept -> int {
    int width = 0;
    for (std::size_t offset = 0; offset < text.size();) {
        const auto scalar = ttytk::detail::decode_utf8_scalar(text, offset);
        const auto added = of(scalar.value, ambiguous_is_wide);
        if (width > std::numeric_limits<int>::max() - added)
            return std::numeric_limits<int>::max();
        width += added;
        offset += scalar.length;
    }
    return width;
}

/**
 * Measure one extended grapheme cluster. Components share the same cells
 * (e.g. a base plus combining marks, Hangul jamo, or a joined emoji).
 */
[[nodiscard]] constexpr auto of_grapheme(const std::string_view cluster,
                                        const bool ambiguous_is_wide = false) noexcept -> int {
    int width = 0;
    char32_t previous = 0;
    std::size_t regional_indicators = 0;
    bool keycap_base = false;
    for (std::size_t offset = 0; offset < cluster.size();) {
        const auto scalar = ttytk::detail::decode_utf8_scalar(cluster, offset);
        const auto cp = scalar.value;
        if ((cp == 0xFE0F && detail::in_intervals(previous, detail::emoji_variation_base)) ||
            (cp == 0x20E3 && keycap_base) ||
            ((cp >= 0x1F1E6 && cp <= 0x1F1FF) && ++regional_indicators == 2)) return 2;
        if (cp != 0xFE0F)
            keycap_base = cp == U'#' || cp == U'*' || (cp >= U'0' && cp <= U'9');
        const auto w = of(cp, ambiguous_is_wide);
        if (w > width) width = w;
        previous = cp;
        offset += scalar.length;
    }
    return width;
}

